<script setup>
import {categories} from '../lib/rules';
defineProps({items:Array,busy:Boolean,query:Object,page:Number});defineEmits(['search','buy','chat','page']);
</script>
<template><section><div class="intro"><div><span class="eyebrow">CAMPUS CIRCULATION</span><h1>旧物有新去处，好物继续发光。</h1><p class="muted">在校园里，让闲置遇见需要它的人。</p></div></div><form class="search" @submit.prevent="$emit('search')"><input aria-label="搜索物品" v-model="query.q" maxlength="120" placeholder="搜索教材、台灯、数码配件…"><select aria-label="分类" v-model="query.category"><option value="">全部分类</option><option v-for="c in categories" :key="c">{{c}}</option></select><button class="primary" :disabled="busy">搜索</button></form><div class="grid"><article v-for="i in items" :key="i.id" class="card"><img v-if="i.image_id" class="item-image" :src="'/api/assets/'+i.image_id" :alt="i.title"><span class="tag">{{i.category}}</span><h2>{{i.title}}</h2><p class="description">{{i.description}}</p><p class="muted">{{i.seller_name}} · {{i.seller_verified?'校园认证':'认证标记未提供'}}</p><div class="row"><strong class="price">¥ {{Number(i.price).toFixed(2)}}</strong><button class="primary" :disabled="busy" @click="$emit('buy',i)">确认下单</button></div><button @click="$emit('chat',i)">咨询卖方</button></article></div><div v-if="!items.length" class="empty">暂时没有找到物品，试试其他关键词。</div><div class="pagination"><button :disabled="page<=1||busy" @click="$emit('page',-1)">上一页</button><span>第 {{page}} 页</span><button :disabled="items.length<20||busy" @click="$emit('page',1)">下一页</button></div></section></template>
